import{_ as s,o as r,c as t,ag as n}from"./chunks/framework.DKalukzk.js";const c=JSON.parse(`{"title":"Analyser une entreprise","description":"Décrire les caractéristiques d'une entreprise et ce qu'elle offre réellement","frontmatter":{"title":"Analyser une entreprise","description":"Décrire les caractéristiques d'une entreprise et ce qu'elle offre réellement"},"headers":[],"relativePath":"modules/04-analyse-info/02-entreprise.md","filePath":"modules/04-analyse-info/02-entreprise.md"}`),i={name:"modules/04-analyse-info/02-entreprise.md"};function o(a,e,l,u,d,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="analyser-une-entreprise" tabindex="-1">Analyser une entreprise <a class="header-anchor" href="#analyser-une-entreprise" aria-label="Permalink to &quot;Analyser une entreprise&quot;">​</a></h1><p>Analyser une entreprise, ce n&#39;est pas seulement dire qu&#39;elle travaille en informatique.</p><p>Il faut être capable d&#39;identifier son <strong>type d&#39;entreprise</strong>, son <strong>domaine informatique principal</strong>, son <strong>secteur d&#39;activité</strong> et ce qu&#39;elle <strong>offre</strong> en matière de <strong>produits</strong> ou de <strong>services</strong>.</p><h2 id="types-d-entreprises-au-quebec" tabindex="-1">Types d&#39;entreprises au Québec <a class="header-anchor" href="#types-d-entreprises-au-quebec" aria-label="Permalink to &quot;Types d&#39;entreprises au Québec&quot;">​</a></h2><p>On peut classer les entreprises et les organismes québécois dans <strong>trois grandes catégories</strong>.</p><h3 id="a-but-lucratif" tabindex="-1">À but lucratif <a class="header-anchor" href="#a-but-lucratif" aria-label="Permalink to &quot;À but lucratif&quot;">​</a></h3><p>Ce sont des entreprises ou des organismes dont l&#39;<strong>objectif principal</strong> est la réalisation de <strong>profits</strong>. On parle alors d&#39;<strong>entreprises privées</strong>, comme <strong>Beenox</strong>, <strong>CGI</strong>, <strong>Libéo</strong>, <strong>Mirego</strong>, <strong>Simons</strong> ou <strong>Beneva</strong>.</p><h3 id="a-but-non-lucratif" tabindex="-1">À but non lucratif <a class="header-anchor" href="#a-but-non-lucratif" aria-label="Permalink to &quot;À but non lucratif&quot;">​</a></h3><p>Ce sont des <strong>associations</strong>, des <strong>sociétés</strong> ou des <strong>clubs</strong> qui visent le bien-être d&#39;une communauté, l&#39;amélioration d&#39;infrastructures locales, les loisirs ou le divertissement, sans en retirer de <strong>bénéfice financier</strong>. Par exemple : le <strong>FEQ</strong>, <strong>Québec Numérique</strong>, <strong>La Ruche</strong>, <strong>Centraide</strong> ou la <strong>Fondation du CHU de Québec</strong>.</p><h3 id="publique-et-parapublique" tabindex="-1">Publique et parapublique <a class="header-anchor" href="#publique-et-parapublique" aria-label="Permalink to &quot;Publique et parapublique&quot;">​</a></h3><p>Ce sont des <strong>organismes</strong> dont la majorité des dirigeantes et dirigeants ou des administratrices et administrateurs sont <strong>nommés par le gouvernement</strong>, et qui bénéficient d&#39;une certaine <strong>autonomie</strong> même si une grande partie de leur <strong>financement</strong> provient de l&#39;<strong>État</strong>. Exemples : <strong>Revenu Québec</strong>, la <strong>SAQ</strong>, la <strong>RAMQ</strong>, le <strong>ministère de l&#39;Éducation</strong> ou l&#39;<strong>Assemblée nationale</strong>.</p><h2 id="domaines-informatiques-a-distinguer" tabindex="-1">Domaines informatiques à distinguer <a class="header-anchor" href="#domaines-informatiques-a-distinguer" aria-label="Permalink to &quot;Domaines informatiques à distinguer&quot;">​</a></h2><p>En ce qui a trait à l&#39;informatique, on s&#39;intéresse surtout à <strong>deux grands domaines informatiques</strong> :</p><ul><li>le <strong>développement d&#39;applications</strong></li><li>l&#39;<strong>administration des réseaux informatiques</strong></li></ul><h3 id="developpement-d-applications" tabindex="-1">Développement d&#39;applications <a class="header-anchor" href="#developpement-d-applications" aria-label="Permalink to &quot;Développement d&#39;applications&quot;">​</a></h3><p>Ce domaine touche entre autres :</p><ul><li>la programmation</li><li>le développement Web</li><li>les applications mobiles</li><li>les bases de données</li><li>les tests et la maintenance logicielle</li></ul><h3 id="administration-des-reseaux-informatiques" tabindex="-1">Administration des réseaux informatiques <a class="header-anchor" href="#administration-des-reseaux-informatiques" aria-label="Permalink to &quot;Administration des réseaux informatiques&quot;">​</a></h3><p>Ce domaine touche entre autres :</p><ul><li>les réseaux</li><li>les serveurs</li><li>la sécurité</li><li>le soutien technique</li><li>la gestion des accès et des équipements</li></ul><h2 id="secteur-d-activite-domaine-d-affaires" tabindex="-1">Secteur d&#39;activité (domaine d&#39;affaires) <a class="header-anchor" href="#secteur-d-activite-domaine-d-affaires" aria-label="Permalink to &quot;Secteur d&#39;activité (domaine d&#39;affaires)&quot;">​</a></h2><p>Le <strong>secteur d&#39;activité</strong> dans lequel une entreprise évolue correspond au <strong>secteur principal</strong> dans lequel elle exerce ses activités.</p><p>Par exemple, une entreprise peut évoluer dans le milieu des <strong>assurances</strong>, du <strong>secteur bancaire</strong>, de la <strong>santé</strong>, de l&#39;<strong>éducation</strong>, du <strong>commerce de détail</strong>, des <strong>médias numériques</strong> ou de la <strong>fonction publique</strong>.</p><p>Cette information aide à mieux comprendre le <strong>type de clientèle visée</strong>, les <strong>besoins</strong> auxquels l&#39;entreprise répond, les <strong>produits ou services</strong> qu&#39;elle offre et les <strong>types de postes</strong> qu&#39;on peut y retrouver.</p><p>Exemples : <strong>Beneva</strong> évolue dans le milieu des assurances, <strong>Revenu Québec</strong> dans le secteur public et les services gouvernementaux, <strong>Libéo</strong> dans le développement Web et les services numériques, et <strong>Simons</strong> dans le commerce de détail.</p><h2 id="produits-et-services" tabindex="-1">Produits et services <a class="header-anchor" href="#produits-et-services" aria-label="Permalink to &quot;Produits et services&quot;">​</a></h2><p>Une entreprise peut offrir :</p><ul><li>des <strong>produits</strong> : logiciel, plateforme, application, outil</li><li>des <strong>services</strong> : consultation, intégration, soutien, maintenance, hébergement</li></ul><p>Certaines entreprises font surtout du <strong>service</strong>. D&#39;autres vendent une <strong>solution précise</strong>. D&#39;autres encore combinent les <strong>deux</strong>.</p><h2 id="ce-qu-il-faut-relever-dans-une-entreprise" tabindex="-1">Ce qu&#39;il faut relever dans une entreprise <a class="header-anchor" href="#ce-qu-il-faut-relever-dans-une-entreprise" aria-label="Permalink to &quot;Ce qu&#39;il faut relever dans une entreprise&quot;">​</a></h2><p>Quand vous analysez une entreprise, essayez de relever :</p><ul><li>son <strong>type d&#39;entreprise</strong></li><li>son <strong>domaine informatique principal</strong></li><li>son <strong>secteur d&#39;activité</strong></li><li>les <strong>produits</strong> qu&#39;elle développe</li><li>les <strong>services</strong> qu&#39;elle offre</li></ul><p>Une entreprise peut bien sûr combiner plusieurs éléments. Par exemple, elle peut toucher à <strong>plus d&#39;un domaine informatique</strong> et offrir à la fois des <strong>produits</strong> et des <strong>services</strong>.</p><h2 id="region-de-quebec" tabindex="-1">Région de Québec <a class="header-anchor" href="#region-de-quebec" aria-label="Permalink to &quot;Région de Québec&quot;">​</a></h2><p>Dans la <strong>région de Québec</strong>, on retrouve des entreprises très différentes :</p><ul><li><strong>agences Web</strong></li><li><strong>firmes de consultation</strong></li><li><strong>entreprises d&#39;assurances ou de services financiers</strong></li><li><strong>organisations publiques</strong></li><li><strong>entreprises de produits numériques</strong></li></ul><h2 id="activite" tabindex="-1">Activité <a class="header-anchor" href="#activite" aria-label="Permalink to &quot;Activité&quot;">​</a></h2><p>Choisissez une <strong>entreprise de Québec</strong> (la même qu&#39;à l&#39;activité précédente) et relevez :</p><ul><li>son <strong>type d&#39;entreprise</strong></li><li>son <strong>domaine informatique principal</strong></li><li>son <strong>secteur d&#39;activité principal</strong></li><li>les <strong>produits et services</strong> offerts</li></ul>',39)])])}const m=s(i,[["render",o]]);export{c as __pageData,m as default};
